LINEAR8 = cto.OptimizationConfig(global_config=cto.OpLinearQuantizerConfig(mode="linear_symmetric"))
BLOCK8 = cto.OpLinearQuantizerConfig(mode="linear_symmetric", granularity="per_block", block_size=32)


def weight_names(path, prefixes):
    "The names of the weights in the Core ML package at `path` that start with one of `prefixes`."
    spec = ct.models.MLModel(str(path), skip_model_load=True).get_spec()
    block = next(iter(spec.mlProgram.functions["main"].block_specializations.values()))
    return [
        op.outputs[0].name for op in block.operations if op.type == "const" and op.outputs[0].name.startswith(prefixes)
    ]


def quantize_coreml(name, config, suffix, palettize=False):
    "IOS/name.mlpackage with its weights compressed by `config`, as IOS/name+suffix, compiled."
    m = ct.models.MLModel(str(IOS / f"{name}.mlpackage"), skip_model_load=True)
    m = (cto.palettize_weights if palettize else cto.linear_quantize_weights)(m, config)
    remove_coreml(IOS / f"{name}{suffix}.mlpackage")
    m.save(str(IOS / f"{name}{suffix}.mlpackage"))
    ct.utils.compile_model(str(IOS / f"{name}{suffix}.mlpackage"), str(IOS / f"{name}{suffix}.mlmodelc"))

