def quantize_front():
    "The front half for download: Tokens with just its text encoder's weights in 8 bits; Prosody all in 8 bits."
    names = weight_names(IOS / "tokens.mlpackage", ("text_encoder_",))
    quantize_coreml("tokens", cto.OptimizationConfig(op_name_configs=dict.fromkeys(names, BLOCK8)), "8")
    quantize_coreml("prosody", cto.OptimizationConfig(global_config=BLOCK8), "8")

