def body_package(T):
    "Notebook 103's body for T frames, as a 16-bit Core ML package in VOICE/parts, made once."
    path = VOICE / "parts" / f"size{T}.mlpackage"
    if not path.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
        dec = exportable_decoder()
        with torch.no_grad():
            f0 = torch.zeros(1, 2 * T)
            args = (torch.zeros(1, 512, T), f0, torch.zeros(1, 2 * T), torch.zeros(1, 128), HarmonicSource(dec)(f0))
            to_coreml(Body(dec), args).save(str(path))
    return path


def shared_body(name, compress=lambda m: m):
    "The body at every size in SIZES, one function each sharing their weights, in IOS/name; `compress` applied first."
    desc = ct.utils.MultiFunctionDescriptor()
    for T in SIZES:
        part = VOICE / "parts" / f"{name}{T}.mlpackage"
        if not part.exists():
            compress(ct.models.MLModel(str(body_package(T)), skip_model_load=True)).save(str(part))
        desc.add_function(str(part), src_function_name="main", target_function_name=f"body{T}")
    desc.default_function_name = f"body{SIZES[0]}"
    remove_coreml(IOS / f"{name}.mlpackage")
    ct.utils.save_multifunction(desc, str(IOS / f"{name}.mlpackage"))
    ct.utils.compile_model(str(IOS / f"{name}.mlpackage"), str(IOS / f"{name}.mlmodelc"))

