def export_voice(voice, folder):
    "A voice's style table as raw little-endian float32, (510, 256), in folder/voice.bin."
    table = pipeline(voice).load_voice(voice).squeeze(1).numpy().astype("<f4")
    folder.mkdir(parents=True, exist_ok=True)
    table.tofile(folder / f"{voice}.bin")
    return table.shape

